-- 계보를 찍는다

@GetMapping(value = "/proxy/tree", produces = "text/plain")
String tree(String name) {
    Object b = ctx.getBean(name);
    StringBuilder sb = new StringBuilder("클래스 " + b.getClass().getName() + "\n");
    for (Class<?> k = b.getClass().getSuperclass(); k != null; k = k.getSuperclass())
        sb.append("  부모 ").append(k.getName()).append('\n');
    for (Class<?> i : b.getClass().getInterfaces())
        sb.append("  구현 ").append(i.getName()).append('\n');
    return sb.toString();
}

