-- 형변환은 런타임에 터진다

@RestController
public class AdminController {
    private final Repo repo;

    @GetMapping("/admin/reset")
    public String reset() {
        ((OrderRepositoryV3) repo).reset();      // 구체 타입으로 형변환
        return "ok";
    }
}

