-- 타깃을 꺼내면

@GetMapping(value = "/proxy/unwrap", produces = "text/plain")
String unwrap(String name) throws Exception {
    Object b = ctx.getBean(name);
    Object t = ((Advised) b).getTargetSource().getTarget();
    return """
        빈:     %s
        타깃:   %s
        같은가: %s
        """.formatted(b.getClass().getName(), t.getClass().getName(), b == t);
}

