@Component
class IdentityCheck implements InitializingBean {
    @Override public void afterPropertiesSet() {
        Object a = ctx.getBean(OrderRepositoryV3.class);
        Object b = ctx.getBean("orderRepositoryV3");
        log.info("빈 == 빈      {}", a == b);
        log.info("빈.equals(타깃) {}", a.equals(target));
        log.info("해시 같은가    {}", a.hashCode() == target.hashCode());
    }
}

