-- 검사로 만든다

@Component
class CastAudit implements InitializingBean {
    @Override public void afterPropertiesSet() {
        for (String name : ctx.getBeanDefinitionNames()) {
            Object b = ctx.getBean(name);
            if (!AopUtils.isJdkDynamicProxy(b)) continue;
            Class<?> t = AopUtils.getTargetClass(b);
            if (!t.getName().startsWith("study.adv")) continue;
            log.warn("형제 프록시 {} 구체 타입 {} 로는 못 받음", name, t.getSimpleName());
        }
    }
}

